// GetExporter builds the metrics exporter once (guarded by the package-level metricExpOnce sync.Once)
// from the given metrics configuration, returning the reader and shutdown function for prometheus or otlp,
// or an error for any other exporter value including empty.
func GetExporter(ctx context.Context, cfg *config.MetricsConfig) (sdkmetric.Reader, func(context.Context) error, error) {
	var reader sdkmetric.Reader
	var shutdown func(context.Context) error
	var buildErr error

	metricExpOnce.Do(func() {
		switch cfg.Exporter {
		case config.MetricsPrometheus:
			exporter, err := prometheus.New()
			if err != nil {
				buildErr = fmt.Errorf("creating prometheus exporter: %w", err)
				return
			}

			provider := sdkmetric.NewMeterProvider(sdkmetric.WithReader(exporter))
			meterProvider = provider
			otel.SetMeterProvider(provider)
			Meter = provider.Meter("github.com/flipt-io/flipt")

			reader = exporter
			shutdown = func(ctx context.Context) error {
				return provider.Shutdown(ctx)
			}

		case config.MetricsOTLP:
			endpoint := cfg.OTLP.Endpoint
			u, err := parseEndpoint(endpoint)
			if err != nil {
				buildErr = fmt.Errorf("parsing OTLP endpoint: %w", err)
				return
			}

			headers := []string{}
			for k, v := range cfg.OTLP.Headers {
				headers = append(headers, k+"="+v)
			}

			var exporter sdkmetric.Reader
			switch u.Scheme {
			case "http", "https":
				grpcOpts := []otlpmetrichttp.Option{
					otlpmetrichttp.WithEndpoint(u.Host),
					otlpmetrichttp.WithURLPath(u.Path),
				}
				if u.Scheme == "https" {
					grpcOpts = append(grpcOpts, otlpmetrichttp.WithTLSClientConfig(nil))
				}
				exp, err := otlpmetrichttp.New(ctx, grpcOpts...)
				if err != nil {
					buildErr = fmt.Errorf("creating OTLP HTTP exporter: %w", err)
					return
				}
				exporter = exp
			case "grpc":
				grpcOpts := []otlpmetricgrpc.Option{
					otlpmetricgrpc.WithEndpoint(u.Host),
				}
				if len(headers) > 0 {
					grpcOpts = append(grpcOpts, otlpmetricgrpc.WithHeaders(headers))
				}
				exp, err := otlpmetricgrpc.New(ctx, grpcOpts...)
				if err != nil {
					buildErr = fmt.Errorf("creating OTLP gRPC exporter: %w", err)
					return
				}
				exporter = exp
			default:
				buildErr = fmt.Errorf("unsupported OTLP scheme: %s", u.Scheme)
