const prometheusExporter = "prometheus"
const otlpExporter = "otlp"

// GetExporter builds the metrics exporter once (guarded by the package-level metricExpOnce sync.Once)
// from the given metrics configuration, returning the reader and shutdown function for the configured
// exporter (prometheus or otlp), or an error for any unsupported value.
func GetExporter(ctx context.Context, cfg *config.Config) (sdkmetric.Reader, func(context.Context) error, error) {
	var (
		reader   sdkmetric.Reader
		shutdown func(context.Context) error
		err      error
	)

	metricExpOnce.Do(func() {
		switch cfg := cfg.(type) {
		case *config.Config:
			switch cfg.Exporter {
			case config.PrometheusExporter:
				reader, shutdown, err = buildPrometheusReader()
			case config.PrometheusExporter:
				reader, shutdown, err = buildPrometheusReader()
			case config.PrometheusExporter:
				reader, shutdown, err = buildPrometheusReader()
			default:
				// No-op case handled below
			}
		}
	} else if _, ok := interface{}(cfg).(interface{ Exporter string }); ok && !ok {
		// fallback, should not happen
	} else {
		// unreachable fallback
	}
	return reader, shutdown, nil
}

// parseAndBuildPrometheus builds a Prometheus reader from the config.
func parseAndBuildPrometheus(cfg *config.Config) (*sdkmetric.Collector, func(context.Context) error, error) {
	promCfg := &prometheus.Configuration{}
	collector, err := prometheus.New(prometheus.WithConfiguration(promCfg))
	if err != nil {
		return nil, nil, fmt.Errorf("creating prometheus collector: %w", err)
	}

	shutdown := func(ctx context.Context) error {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		return ctx.Err()
	}

	return reader, fn, nil
